/**
 * Fonts for the generated social cards (next/og / Satori), base64-embedded so
 * they load identically in Turbopack dev, the production build, and serverless
 * (no fetch(import.meta.url) - unimplemented in Turbopack - and no fs tracing).
 * Regenerate from src/og/fonts/*.woff if the faces change.
 */
export interface OgFont { name: string; data: ArrayBuffer; weight: 400|500|600|700; style: "normal"; }

const sg700 = "";
const sg500 = "";
const in600 = "";
const in500 = "";

function ab(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return u8.buffer;
}

let cached: OgFont[] | null = null;
export async function ogFonts(): Promise<OgFont[]> {
  if (cached) return cached;
  cached = [
    { name: "Space Grotesk", data: ab(sg700), weight: 700, style: "normal" },
    { name: "Space Grotesk", data: ab(sg500), weight: 500, style: "normal" },
    { name: "Inter", data: ab(in600), weight: 600, style: "normal" },
    { name: "Inter", data: ab(in500), weight: 500, style: "normal" },
  ];
  return cached;
}

export const OG_SIZE = { width: 1200, height: 630 };
